ioc_context = {
    "1.2.3.4": {"reputation": "malicious", "confidence": 85},
    "5.6.7.8": {"reputation": "unknown", "confidence": 40}
}

def is_high_risk(ioc):
    data = ioc_context.get(ioc)
    if not data:
        return False
    return data["reputation"] == "malicious" and data["confidence"] >= 70

print(is_high_risk("1.2.3.4"))
